<script setup>
import { ref } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { ArrowLeft, Sparkles, CheckCircle2, AlertTriangle, FileText, Send, RotateCcw } from '@/views/enterprise/components/icons'
import ToastMessage from '@/views/enterprise/components/ToastMessage.vue'
import { api, reserveApi } from '@/views/enterprise/api/contract'

const router=useRouter(); const route=useRoute(); const toast=ref(''); const recommendation=ref('推荐'); const comment=ref('')
const dimensions=ref([{name:'技术理论',score:85,evidence:'能解释 Vue 3 响应式差异，覆盖主要边界。'},{name:'动手实践',score:78,evidence:'给出了长列表优化方案，但量化收益不足。'},{name:'逻辑思维',score:88,evidence:'回答先结论后展开，结构完整。'},{name:'沟通表达',score:82,evidence:'表达清晰，能根据追问补充细节。'},{name:'文化匹配度',score:80,evidence:'体现跨团队协作经验，需继续核实稳定性。'}])
function notify(v){toast.value=v;setTimeout(()=>toast.value='',2000)}
function publish(){reserveApi(api.sessions.publishEvaluation,{sessionId:route.params.id,recommendation:recommendation.value==='强烈推荐'?1:recommendation.value==='推荐'?2:recommendation.value==='待定'?3:4,comment:comment.value,notifyCandidate:true});notify('评估发布接口已预留')}
function reject(){reserveApi(api.sessions.evaluation,{sessionId:route.params.id,target:'ai',reason:'评分依据不足'});notify('已提交重评请求')}
</script>

<template>
  <div class="page evaluation-page"><button class="back" @click="router.back()"><ArrowLeft :size="15"/>返回面试列表</button><div class="page-heading"><div><h1>阶段评估 · 专业技术面</h1><p>王芳 · 高级前端工程师 · AI + HR 协同 · 会话 SES-6001</p></div><span class="pill orange">待 HR 审核</span></div><div class="evaluation-grid"><main><section class="card score-card"><div class="score-overview"><div><span class="eyebrow"><Sparkles :size="14"/>AI 阶段评估</span><strong>82.6<small> / 100</small></strong><p>基于对话证据、评分卡和人工补充生成</p></div><div class="ring">83</div></div><div class="score-bars"><div v-for="item in dimensions" :key="item.name"><span>{{item.name}}</span><b>{{item.score}}</b><i><u :style="{width:`${item.score}%`}"/></i></div></div></section><section class="card evidence-card"><div class="section-title"><span>评分依据与证据</span><FileText :size="16"/></div><article v-for="item in dimensions" :key="item.name"><div><b>{{item.name}}</b><span class="pill">{{item.score}} 分</span></div><p>{{item.evidence}}</p></article></section></main><aside><section class="card decision-card"><div class="section-title"><span>HR 终审</span><CheckCircle2 :size="17" class="green"/></div><label>阶段建议</label><div class="decision-options"><button v-for="item in ['强烈推荐','推荐','待定','淘汰']" :key="item" :class="{active:recommendation===item}" @click="recommendation=item">{{item}}</button></div><label>HR 补充评语</label><textarea v-model="comment" class="textarea" placeholder="补充阶段结论、风险或下一阶段重点…"/><div class="review-note"><AlertTriangle :size="14"/><span>AI 只能生成建议，最终流转由授权 HR 或用人经理确认。</span></div><button class="btn primary full" @click="publish"><Send :size="15"/>确认并发布评估</button><button class="btn full" @click="reject"><RotateCcw :size="15"/>驳回并要求重评</button></section><section class="card next-card"><b>发布后动作</b><p>推荐：生成下一阶段排期 · 待定：进入 HR 待办 · 淘汰：发送关怀通知并归档</p></section></aside></div><ToastMessage :message="toast"/></div>
</template>

